import "./button.css";

import type { ComponentProps, KeyboardEvent, MouseEvent, ReactNode } from "react";
import { cx } from "./cx";
import { Spinner } from "./spinner";

export { ButtonGroup } from "./button-group";
export type { ButtonGroupProps } from "./button-group";

export type ButtonVariant =
  | "solid"
  | "outline"
  | "ghost"
  | "danger"
  | "success"
  | "warning"
  | "link";

type Shared = {
  variant?: ButtonVariant;
  round?: boolean;
  pending?: boolean;
  disabled?: boolean;
};

type Named =
  | { icon?: false }
  | { icon: true; "aria-label": string }
  | { icon: true; "aria-labelledby": string };

type AsButton = Shared &
  Named &
  Omit<ComponentProps<"button">, "href"> & {
    href?: undefined;
  };

type AsLink = Shared &
  Named &
  Omit<ComponentProps<"a">, "href" | "type"> & {
    href: string;
  };

export type ButtonProps = AsButton | AsLink;

function warnIconName(
  icon: boolean,
  named: {
    "aria-label"?: string | undefined;
    "aria-labelledby"?: string | undefined;
  },
) {
  if (process.env.NODE_ENV === "production" || !icon) return;
  if (named["aria-label"] || named["aria-labelledby"]) return;
  console.warn("Button: icon requires aria-label or aria-labelledby.");
}

function blocked(
  pending: boolean,
  disabled: boolean | undefined,
  event: MouseEvent | KeyboardEvent,
) {
  if (!pending && !disabled) return false;
  event.preventDefault();
  event.stopPropagation();
  return true;
}

export function Button({
  variant = "solid",
  icon = false,
  round = false,
  pending = false,
  className,
  disabled,
  children,
  onClick,
  onKeyDown,
  ...rest
}: ButtonProps) {
  const href = "href" in rest ? rest.href : undefined;
  const type = "type" in rest && rest.type ? rest.type : "button";
  const classNames = cx("ns-button", className);
  const body: ReactNode = (
    <>
      {pending ? <Spinner /> : null}
      {children}
    </>
  );

  warnIconName(icon, rest);

  const marks = {
    className: classNames,
    "data-variant": variant,
    "data-icon": icon ? "" : undefined,
    "data-round": round ? "" : undefined,
    "data-pending": pending ? "" : undefined,
    "aria-busy": pending || undefined,
  } as const;

  const guards =
    pending || onClick || onKeyDown
      ? {
          onClick: (
            event: MouseEvent<HTMLButtonElement | HTMLAnchorElement>,
          ) => {
            if (blocked(pending, disabled, event)) return;
            onClick?.(event as never);
          },
          onKeyDown: (
            event: KeyboardEvent<HTMLButtonElement | HTMLAnchorElement>,
          ) => {
            if (
              (pending || disabled) &&
              (event.key === "Enter" || event.key === " ")
            ) {
              blocked(true, disabled, event);
              return;
            }
            onKeyDown?.(event as never);
          },
        }
      : {};

  if (href) {
    const { href: dest, ...linkRest } = rest as AsLink;
    return (
      <a
        {...linkRest}
        {...marks}
        {...guards}
        href={dest}
        {...(disabled ? { tabIndex: -1, "aria-disabled": true as const } : {})}
      >
        {body}
      </a>
    );
  }

  const { type: _type, ...buttonRest } = rest as AsButton;
  return (
    <button
      {...buttonRest}
      {...marks}
      {...guards}
      type={pending ? "button" : type}
      disabled={disabled}
    >
      {body}
    </button>
  );
}

import "./button.css";

import type { ComponentProps } from "react";
import { cx } from "./cx";

export type ButtonGroupProps = ComponentProps<"div">;

export function ButtonGroup({ className, ...rest }: ButtonGroupProps) {
  return <div className={cx("ns-button-group", className)} role="group" {...rest} />;
}

@layer components {
  .ns-button {
    appearance: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    --ns-control: var(
      --control,
      calc(
        var(--type-md, 1rem) * var(--leading-tight, 1.25) + var(--space-4, 0.49rem) *
          2
      )
    );
    gap: var(--space-3, 0.39rem);
    margin: 0;
    min-height: var(--ns-control);
    padding: var(--space-2, 0.31rem) var(--space-6, 0.76rem);
    --ns-key: var(--key, #a2c7ff);
    --ns-on-key: var(--on-key, #111);
    --ns-key-mix: var(--chrome-mix, #fff);
    border: 1px solid var(--face-line, #626262);
    border-radius: var(--radius, 0.4rem);
    background-clip: padding-box;
    font: inherit;
    line-height: var(--leading-tight, 1.25);
    letter-spacing: inherit;
    cursor: pointer;
    user-select: none;
    text-decoration: none;
    color: var(--ns-on-key);
    background: var(--key-face);
    box-shadow: var(--float, 0 8px 20px rgb(0 0 0 / 12%));
    -webkit-tap-highlight-color: transparent;
    transition:
      color var(--duration, 200ms) var(--ease, cubic-bezier(0.22, 1, 0.36, 1)),
      background var(--duration, 200ms) var(--ease, cubic-bezier(0.22, 1, 0.36, 1)),
      border-color var(--duration, 200ms) var(--ease, cubic-bezier(0.22, 1, 0.36, 1)),
      box-shadow var(--duration, 200ms) var(--ease, cubic-bezier(0.22, 1, 0.36, 1)),
      transform var(--duration, 200ms) var(--ease, cubic-bezier(0.22, 1, 0.36, 1));
  }

  .ns-button[data-variant="outline"] {
    color: var(--text-heading, #111);
    border-color: var(--face-line, #626262);
    background: var(--face);
    box-shadow: var(--float, 0 8px 20px rgb(0 0 0 / 12%));
  }

  .ns-button[data-variant="ghost"] {
    color: var(--text-heading, #111);
    border-color: transparent;
    background: transparent;
    box-shadow: var(--flat);
  }

  .ns-button[data-variant="danger"],
  .ns-button[data-variant="success"],
  .ns-button[data-variant="warning"] {
    --ns-on-key: var(--on-key, #111);
    --ns-key-mix: var(--chrome-mix, #fff);
    --key-face: linear-gradient(
      180deg,
      color-mix(in srgb, var(--ns-key) 18%, var(--ns-key-mix)) 0%,
      color-mix(in srgb, var(--ns-key) 38%, var(--ns-key-mix)) 18%,
      color-mix(in srgb, var(--ns-key) 58%, var(--ns-key-mix)) 50%,
      color-mix(in srgb, var(--ns-key) 62%, var(--ns-key-mix)) 80%,
      color-mix(in srgb, var(--ns-key) 55%, var(--ns-key-mix)) 100%
    );
    --key-face-hover: linear-gradient(
      180deg,
      color-mix(in srgb, var(--ns-key) 12%, var(--ns-key-mix)) 0%,
      color-mix(in srgb, var(--ns-key) 30%, var(--ns-key-mix)) 18%,
      color-mix(in srgb, var(--ns-key) 50%, var(--ns-key-mix)) 50%,
      color-mix(in srgb, var(--ns-key) 54%, var(--ns-key-mix)) 100%
    );
    --key-face-press: linear-gradient(
      180deg,
      color-mix(in srgb, var(--ns-key) 38%, var(--ns-key-mix)) 0%,
      color-mix(in srgb, var(--ns-key) 62%, var(--ns-key-mix)) 50%,
      color-mix(in srgb, var(--ns-key) 72%, var(--ns-key-mix)) 100%
    );
  }

  .ns-button[data-variant="danger"] {
    --ns-key: var(--error, #8f3232);
    --ns-on-key: var(--on-error, #fff);
  }

  .ns-button[data-variant="success"] {
    --ns-key: var(--success, #2f6b3a);
    --ns-on-key: var(--on-success, #fff);
  }

  .ns-button[data-variant="warning"] {
    --ns-key: var(--warning, #8a5a12);
    --ns-on-key: var(--on-warning, #fff);
  }

  .ns-button[data-variant="link"] {
    min-height: 0;
    padding: 0;
    border: 0;
    background: none;
    box-shadow: none;
    color: var(--text-heading, #111);
    text-decoration-line: underline;
    text-decoration-style: dotted;
    text-underline-offset: 0.3em;
    text-decoration-thickness: 1px;
    text-decoration-color: color-mix(in srgb, currentColor 40%, transparent);
  }

  .ns-button > svg,
  .ns-button .ns-spinner {
    width: 1em;
    height: 1em;
    flex-shrink: 0;
    pointer-events: none;
  }

  .ns-button[data-pending] > svg {
    display: none;
  }

  .ns-button[data-icon] {
    width: var(--ns-control);
    padding-inline: 0;
  }

  .ns-button[data-icon][data-variant="link"] {
    width: auto;
    padding-inline: var(--space-2, 0.31rem);
  }

  .ns-button[data-round] {
    border-radius: 999px;
  }

  .ns-button:disabled,
  .ns-button[aria-disabled="true"] {
    cursor: not-allowed;
    opacity: 0.5;
    box-shadow: var(--flat);
    pointer-events: none;
  }

  .ns-button[data-variant="solid"]:disabled,
  .ns-button[data-variant="solid"][aria-disabled="true"],
  .ns-button[data-variant="danger"]:disabled,
  .ns-button[data-variant="danger"][aria-disabled="true"],
  .ns-button[data-variant="success"]:disabled,
  .ns-button[data-variant="success"][aria-disabled="true"],
  .ns-button[data-variant="warning"]:disabled,
  .ns-button[data-variant="warning"][aria-disabled="true"] {
    background: var(--key-face);
  }

  .ns-button[data-variant="outline"]:disabled,
  .ns-button[data-variant="outline"][aria-disabled="true"] {
    background: var(--face);
  }

  .ns-button[data-variant="ghost"]:disabled,
  .ns-button[data-variant="ghost"][aria-disabled="true"] {
    background: transparent;
    border-color: transparent;
  }

  .ns-button[data-pending] {
    cursor: wait;
    pointer-events: none;
  }

  .ns-button:focus-visible {
    outline: 2px solid var(--focus, color-mix(in srgb, var(--text-heading, #111) 70%, transparent));
    outline-offset: 2px;
  }

  .ns-button:active:not(:disabled):not([aria-disabled="true"]):not(
      [data-variant="link"]
    ) {
    transform: translateY(2px);
  }

  @media (hover: hover) {
    .ns-button[data-variant="solid"]:hover:not(:disabled):not(
        [aria-disabled="true"]
      ),
    .ns-button[data-variant="danger"]:hover:not(:disabled):not(
        [aria-disabled="true"]
      ),
    .ns-button[data-variant="success"]:hover:not(:disabled):not(
        [aria-disabled="true"]
      ),
    .ns-button[data-variant="warning"]:hover:not(:disabled):not(
        [aria-disabled="true"]
      ) {
      background: var(--key-face-hover);
    }

    .ns-button[data-variant="outline"]:hover:not(:disabled):not(
        [aria-disabled="true"]
      ) {
      background: var(--face-hover, var(--face));
    }

    .ns-button[data-variant="ghost"]:hover:not(:disabled):not(
        [aria-disabled="true"]
      ) {
      background: var(--bg-hover, #f3f2f1);
      box-shadow: var(--flat);
    }

    .ns-button[data-variant="link"]:hover:not(:disabled):not(
        [aria-disabled="true"]
      ) {
      text-decoration-color: currentColor;
    }
  }

  .ns-button[data-variant="solid"]:active:not(:disabled):not(
      [aria-disabled="true"]
    ),
  .ns-button[data-variant="danger"]:active:not(:disabled):not(
      [aria-disabled="true"]
    ),
  .ns-button[data-variant="success"]:active:not(:disabled):not(
      [aria-disabled="true"]
    ),
  .ns-button[data-variant="warning"]:active:not(:disabled):not(
      [aria-disabled="true"]
    ) {
    background: var(--key-face-press);
    box-shadow: var(--float-press);
  }

  .ns-button[data-variant="outline"]:active:not(:disabled):not(
      [aria-disabled="true"]
    ) {
    background: var(--face-press);
    box-shadow: var(--float-press);
  }

  .ns-button[data-variant="ghost"]:active:not(:disabled):not(
      [aria-disabled="true"]
    ) {
    background: var(--bg-hover, #f3f2f1);
    box-shadow: var(--flat);
  }

  .ns-button[data-variant="link"]:active:not(:disabled):not(
      [aria-disabled="true"]
    ) {
    transform: none;
    box-shadow: none;
  }

  .ns-button-group > .ns-button:active:not(:disabled):not(
      [aria-disabled="true"]
    ) {
    transform: none;
  }

  .ns-button-group {
    display: inline-flex;
    align-items: stretch;
  }

  .ns-button-group > .ns-button {
    position: relative;
    border-radius: 0;
  }

  .ns-button-group > .ns-button:first-child {
    border-start-start-radius: var(--radius, 0.4rem);
    border-end-start-radius: var(--radius, 0.4rem);
  }

  .ns-button-group > .ns-button:last-child {
    border-start-end-radius: var(--radius, 0.4rem);
    border-end-end-radius: var(--radius, 0.4rem);
  }

  .ns-button-group > .ns-button:not(:first-child) {
    margin-inline-start: -1px;
  }

  .ns-button-group > .ns-button:focus-visible {
    z-index: 1;
  }

  @media (prefers-reduced-motion: reduce) {
    .ns-button {
      transition: none;
    }

    .ns-button:active:not(:disabled):not([aria-disabled="true"]) {
      transform: none;
    }
  }
}

a.ns-button {
  text-decoration: none;
  color: var(--ns-on-key, var(--on-key, #111));
}

a.ns-button[data-variant="ghost"],
a.ns-button[data-variant="outline"],
a.ns-button[data-variant="link"] {
  color: var(--text-heading, #111);
}
